public static void main(String[] args){
    PrintWriter out = new PrintWriter(System.out);
    InputReader sc = new InputReader(System.in);		
    long n = sc.nextLong();
    long ans = 0;
    for (long num = 1; num <= n; num++) {
        long sumOfDigits = 0;
        long temp = num;
        while (temp > 0) {
            sumOfDigits += temp % 10;
            temp /= 10;
        }
        if (num % sumOfDigits == 0) {
            ans++;
        }
    }
    System.out.println(ans);
}
